-- Atomic task claims, stale fencing, scope/options, durable submit caps and no replay.
begin;
select set_config('request.jwt.claim.role','service_role',true);
update public.apply_tasks set created_at=case when job->>'jobUrl'='https://boards.greenhouse.io/proof/jobs/1' then now()-interval '1 day' else now() end;
do $$ declare a jsonb; b jsonb; answer jsonb; t jsonb; q jsonb; p jsonb; r jsonb; lease jsonb; id uuid; begin
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'tasks.claim','{"limit":1,"leaseSeconds":30}');
  t:=a->'tasks'->0;
  perform public.test_apply_pipeline_assert(t->>'status'='in_progress' and t->>'lease_version'='1' and t ? 'lease_nonce','claimed task has version, nonce and expiry');
  lease:=jsonb_build_object('taskId',t->>'id','leaseVersion',(t->>'lease_version')::int,'leaseNonce',t->>'lease_nonce');
  b:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'tasks.claim','{"limit":1}');
  perform public.test_apply_pipeline_assert(b->'tasks'->0->>'id'<>t->>'id','next claim continues other jobs');
  perform public.test_apply_pipeline_denied(format('select public.service_apply_pipeline_dispatch(%L,repeat(''a'',64),''tasks.renew'',%L)', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', (lease||'{"leaseVersion":99}')::text));
  q:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'questions.queue',lease||'{"question":{"meaning":"unknown:portfolio access","questionText":"What is your portfolio access code?","controlType":"select","options":["Public","Private"],"context":{"application":"https://boards.greenhouse.io/proof/jobs/1"},"scope":"application","scopeKey":"https://boards.greenhouse.io/proof/jobs/1","questionKey":"untrusted-caller-key"}}');
  perform public.test_apply_pipeline_assert(q->'question'->>'question_key'<>'untrusted-caller-key','server canonical key, not caller hash');
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'tasks.report',lease||'{"status":"waiting_answer","reason":"Confirmed answer needed"}');
  perform public.test_apply_pipeline_assert(a->'task'->>'status'='waiting_answer','unknown required control blocks just this task');
  perform set_config('request.jwt.claim.role','authenticated',true);
  execute 'set local role authenticated';
  perform set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
  perform public.test_apply_pipeline_denied(format('select public.my_apply_pipeline_action(''questions.answer'',%L)',jsonb_build_object('questionId',q->'question'->>'id','answer','Public','scope','global','confirm',true)::text));
  perform public.test_apply_pipeline_denied(format('select public.my_apply_pipeline_action(''questions.answer'',%L)',jsonb_build_object('questionId',q->'question'->>'id','answer','Not an option','scope','application','scopeKey','https://boards.greenhouse.io/proof/jobs/1','confirm',true)::text));
  a:=public.my_apply_pipeline_action('questions.answer',jsonb_build_object('questionId',q->'question'->>'id','answer','Private','scope','application','scopeKey','https://boards.greenhouse.io/proof/jobs/1','confirm',true));
  answer:=a->'answer';
  perform public.test_apply_pipeline_assert(a->'answer'->>'provenance'='user' and a->>'revision'='2','user explicitly confirms exact scoped answer');
  execute 'reset role';
  execute 'set local role service_role';
  perform set_config('request.jwt.claim.role','service_role',true);
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'tasks.claim','{"limit":1}');
  t:=a->'tasks'->0;
  perform public.test_apply_pipeline_assert(t->>'id'=lease->>'taskId' and (t->>'lease_version')::int>1 and t->>'answers_revision'='2','answer resumes only scoped waiting task, new fence');
  lease:=jsonb_build_object('taskId',t->>'id','leaseVersion',(t->>'lease_version')::int,'leaseNonce',t->>'lease_nonce');
  r:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'submission.reserve',lease||jsonb_build_object('profileRevision',1,'settingsRevision',2,'answersRevision',2,'siteAllowed',true,'accountVerified',true,'requiredComplete',true,'answerIds',jsonb_build_array(answer->>'id'),'idempotencyKey','proof-one'));
  perform public.test_apply_pipeline_assert(r->'reservation'->>'status'='reserved','reservation exists before submit');
  perform public.test_apply_pipeline_denied(format('select public.service_apply_pipeline_dispatch(%L,repeat(''a'',64),''tasks.report'',%L)', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', (lease||'{"status":"submitted"}')::text));
  perform public.test_apply_pipeline_denied(format('select public.service_apply_pipeline_dispatch(%L,repeat(''a'',64),''submission.finish'',%L)', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', (lease||jsonb_build_object('reservationId',r->'reservation'->>'id','reservationNonce',r->'reservation'->>'nonce','outcome','submitted','evidence',jsonb_build_object('kind','confirmation_page','text','Please submit your application')))::text));
  perform public.test_apply_pipeline_denied(format('select public.service_apply_pipeline_dispatch(%L,repeat(''a'',64),''submission.finish'',%L)', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', (lease||jsonb_build_object('reservationId',r->'reservation'->>'id','reservationNonce',r->'reservation'->>'nonce','outcome','submitted','evidence',jsonb_build_object('kind','confirmation_page','text','Application submitted','url','https://unrelated.example/receipt')))::text));
  perform public.test_apply_pipeline_denied(format('select public.service_apply_pipeline_dispatch(%L,repeat(''a'',64),''submission.finish'',%L)', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', (lease||jsonb_build_object('reservationId',r->'reservation'->>'id','reservationNonce',r->'reservation'->>'nonce','outcome','submitted','evidence',jsonb_build_object('kind','confirmation_page','text','Application not submitted, error')))::text));
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'submission.finish',lease||jsonb_build_object('reservationId',r->'reservation'->>'id','reservationNonce',r->'reservation'->>'nonce','outcome','unverified'));
  perform public.test_apply_pipeline_assert(a->'reservation'->>'status'='unverified','uncertain attempt is explicit, not successful');
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'tasks.claim','{"limit":10}');
  perform public.test_apply_pipeline_assert(not exists(select 1 from jsonb_array_elements(a->'tasks') x where x->>'id'=t->>'id'),'reserved uncertain submit can never be re-claimed');
  a:=public.service_apply_pipeline_dispatch('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'submission.finish',lease||jsonb_build_object('reservationId',r->'reservation'->>'id','reservationNonce',r->'reservation'->>'nonce','outcome','submitted','evidence',jsonb_build_object('kind','confirmation_page','text','Your application has been received','url','https://boards.greenhouse.io/proof/jobs/1')));
  perform public.test_apply_pipeline_assert(a->'reservation'->>'status'='submitted','positive evidence can reconcile same durable attempt');
end $$;
reset role;
rollback;
